#wz{position:fixed;inset:0;z-index:72;background:var(--b0);display:none;overflow:auto}#wz.show{display:block}#wz .wrap{max-width:760px;margin:0 auto;padding:64px 32px 80px}#wz .steps{display:flex;gap:8px;margin-bottom:28px}#wz .steps i{width:28px;height:4px;border-radius:2px;background:var(--b3)}#wz .steps i.on{background:var(--acc)}#wz .steps i.done{background:var(--agent)}
